// Extraire le corps de la requête
const body = $input.first().json.body ?? $input.first().json;
const message = body.message ?? '';
const sessionId = body.session_id ?? 'default';

// Charger la session depuis le static data du workflow
const store = $getWorkflowStaticData('global');
if (!store.sessions) store.sessions = {};

const session = store.sessions[sessionId] ?? {
  produit_actif: null,
  produits_recents: [],
  derniere_requete_produit: null,
  dernier_statut_recherche: null,
  dernier_resultat_recherche: null,
  produits_deja_envoyes: [],
  derniere_limite_recherche: 5
};

return [{ json: { message, session_id: sessionId, session } }];

const text = $fromAI('text', 'Le texte à vectoriser (requête produit du client)', 'string');

const response = await $helpers.httpRequest({
  method: 'POST',
  url: 'https://api.openai.com/v1/embeddings',
  headers: {
    'Authorization': `Bearer ${$env.OPENAI_API_KEY}`,
    'Content-Type': 'application/json'
  },
  body: JSON.stringify({
    model: 'text-embedding-3-small',
    input: text,
    dimensions: 1536
  })
});

// Retourner le vecteur sérialisé (l'agent le passera à match_images)
return JSON.stringify(response.data[0].embedding);

const embeddingStr = $fromAI('embedding_json', 'Le JSON string du tableau de 1536 floats retourné par embed_text', 'string');
const matchThreshold = $fromAI('match_threshold', 'Seuil de similarité cosine (défaut 0.2)', 'number') ?? 0.2;
const matchCount = $fromAI('match_count', 'Nombre maximum de résultats à retourner (défaut 5, max 20)', 'number') ?? 5;

const embedding = JSON.parse(embeddingStr);

const SUPABASE_URL = 'https://ymdngagxbpjqanczloyv.supabase.co';
const ANON_KEY = $env.SUPABASE_ANON_KEY;

const response = await $helpers.httpRequest({
  method: 'POST',
  url: `${SUPABASE_URL}/rest/v1/rpc/match_images`,
  headers: {
    'apikey': ANON_KEY,
    'Authorization': `Bearer ${ANON_KEY}`,
    'Content-Type': 'application/json'
  },
  body: JSON.stringify({
    query_embedding: embedding,
    match_threshold: matchThreshold,
    match_count: matchCount
  })
});

return JSON.stringify(response);

