const agentOutput = $input.first().json.output ?? '';

// Parser le JSON retourné par l'orchestrateur
let payload;
try {
  // Nettoyer les balises markdown si présentes
  const cleaned = agentOutput.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  payload = JSON.parse(cleaned);
} catch (e) {
  payload = {
    type: 'erreur_parse',
    message: 'Impossible de parser la sortie orchestrateur : ' + e.message,
    raw: agentOutput
  };
}

// Mettre à jour la session dans le static data
const sessionId = $('Init Session').first().json.session_id;
const store = $getWorkflowStaticData('global');
if (!store.sessions) store.sessions = {};

const currentSession = store.sessions[sessionId] ?? {};
const update = payload.session_update ?? {};

if (update.produit_actif !== undefined) currentSession.produit_actif = update.produit_actif;
if (update.produits_recents?.length) currentSession.produits_recents = update.produits_recents.slice(-5);
if (update.derniere_requete_produit) currentSession.derniere_requete_produit = update.derniere_requete_produit;
if (update.dernier_statut_recherche) currentSession.dernier_statut_recherche = update.dernier_statut_recherche;
if (update.dernier_resultat_recherche) currentSession.dernier_resultat_recherche = update.dernier_resultat_recherche;
if (update.produits_deja_envoyes) currentSession.produits_deja_envoyes = update.produits_deja_envoyes;
if (update.derniere_limite_recherche) currentSession.derniere_limite_recherche = update.derniere_limite_recherche;

store.sessions[sessionId] = currentSession;

// Retirer session_update du payload final
delete payload.session_update;

return [{ json: { payload, session_id: sessionId } }];
